content:
:root {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: #f3f4f6;
  color: #1f2937;
  line-height: 1.5;
}

body {
  margin: 0;
  padding: 0;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
}

.app-container {
  width: 100%;
  max-width: 500px;
  margin: 40px 16px;
  background-color: #ffffff;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  padding: 24px;
  box-sizing: border-box;
}

.header {
  margin-bottom: 24px;
  text-align: center;
}

.title {
  font-size: 1.75rem;
  font-weight: 700;
  color: #111827;
  margin: 0;
}

.input-form {
  display: flex;
  gap: 8px;
  margin-bottom: 24px;
}

.todo-input {
  flex: 1;
  padding: 10px 14px;
  font-size: 1rem;
  border: 1px solid #d1d5db;
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.todo-input:focus {
  border-color: #2563eb;
  box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.15);
}

.btn {
  padding: 10px 16px;
  font-size: 1rem;
  font-weight: 500;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s, opacity 0.2s;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background-color: #3b82f6;
  color: #ffffff;
}

.btn-primary:hover {
  background-color: #2563eb;
}

.btn-primary:focus {
  outline: none;
  box-shadow: 0 0 0 4px rgba(59, 130, 246, 0.3);
}

.todo-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.todo-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background-color: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  transition: background-color 0.2s;
}

.todo-item:hover {
  background-color: #f3f4f6;
}

.todo-checkbox {
  width: 20px;
  height: 20px;
  cursor: pointer;
  accent-color: #3b82f6;
}

.todo-checkbox:focus {
  outline: 2px solid #3b82f6;
  outline-offset: 2px;
}

.todo-text {
  flex: 1;
  margin-left: 12px;
  font-size: 1rem;
  color: #374151;
  word-break: break-all;
}

.todo-checkbox:checked + .todo-text {
  text-decoration: line-through;
  color: #9ca3af;
}

.todo-delete {
  background-color: transparent;
  color: #ef4444;
  border: none;
  padding: 6px 10px;
  font-size: 0.875rem;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s, color 0.2s;
}

.todo-delete:hover {
  background-color: #fee2e2;
  color: #dc2626;
}

.todo-delete:focus {
  outline: none;
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.3);
}

@media (max-width: 480px) {
  body {
    align-items: stretch;
  }

  .app-container {
    margin: 0;
    padding: 16px;
    border-radius: 0;
    min-height: 100vh;
    box-shadow: none;
  }

  .title {
    font-size: 1.5rem;
  }

  .todo-item {
    padding: 10px 12px;
  }
}

/**
 * Todoアイテムのデータ構造を定義するインターフェース
 */
export interface Todo {
  /** タスクの一意な識別子 */
  id: string;
  /** タスクの内容 */
  text: string;
  /** タスクが完了しているかどうか */
  completed: boolean;
  /** タスクの作成日時（オプション） */
  createdAt?: string;
  /** タスクの優先度（オプション） */
  priority?: 'low' | 'medium' | 'high';
  /** タスクのカテゴリ（オプション） */
  category?: string;
}

import { useState, useEffect } from 'react';
import { Todo } from './types';
import './index.css';

const LOCAL_STORAGE_KEY = 'todos-app';

export default function App() {
  const [todos, setTodos] = useState<Todo[]>(() => {
    try {
      const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (saved) {
        return JSON.parse(saved);
      }
    } catch (e) {
      console.error(e);
    }
    return [
      { id: '1', text: 'Reactの勉強をする', completed: false },
      { id: '2', text: '買い物に行く', completed: false },
      { id: '3', text: '部屋の掃除をする', completed: false },
    ];
  });
  const [inputText, setInputText] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editText, setEditText] = useState('');

  useEffect(() => {
    try {
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(todos));
    } catch (e) {
      console.error(e);
    }
  }, [todos]);

  const handleAddTodo = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputText.trim()) return;

    const newTodo: Todo = {
      id: Date.now().toString(),
      text: inputText.trim(),
      completed: false,
    };

    setTodos([...todos, newTodo]);
    setInputText('');
  };

  const handleToggleTodo = (id: string) => {
    setTodos(
      todos.map((todo) =>
        todo.id === id ? { ...todo, completed: !todo.completed } : todo
      )
    );
  };

  const handleDeleteTodo = (id: string) => {
    setTodos(todos.filter((todo) => todo.id !== id));
  };

  const handleStartEdit = (todo: Todo) => {
    setEditingId(todo.id);
    setEditText(todo.text);
  };

  const handleSaveEdit = (id: string) => {
    if (!editText.trim()) return;
    setTodos(
      todos.map((todo) =>
        todo.id === id ? { ...todo, text: editText.trim() } : todo
      )
    );
    setEditingId(null);
    setEditText('');
  };

  const handleCancelEdit = () => {
    setEditingId(null);
    setEditText('');
  };

  const remainingCount = todos.filter((todo) => !todo.completed).length;

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">やることリスト</h1>
        <p className="todo-counter" style={{ marginTop: '8px', color: '#6b7280', fontSize: '0.875rem' }}>
          残りタスク: {remainingCount} / 全体: {todos.length}
        </p>
      </header>

      <form className="input-form" onSubmit={handleAddTodo}>
        <input
          type="text"
          className="todo-input"
          placeholder="新しいやること..."
          value={inputText}
          onChange={(e) => setInputText(e.target.value)}
        />
        <button type="submit" className="btn btn-primary">
          追加
        </button>
      </form>

      <ul className="todo-list">
        {todos.map((todo) => (
          <li key={todo.id} className="todo-item">
            <input
              type="checkbox"
              className="todo-checkbox"
              checked={todo.completed}
              onChange={() => handleToggleTodo(todo.id)}
            />
            {editingId === todo.id ? (
              <div style={{ display: 'flex', flex: 1, gap: '8px', marginLeft: '12px' }}>
                <input
                  type="text"
                  className="todo-input"
                  value={editText}
                  onChange={(e) => setEditText(e.target.value)}
                  style={{ padding: '4px 8px', fontSize: '1rem' }}
                />
                <button
                  type="button"
                  className="btn btn-primary"
                  style={{ padding: '4px 8px', fontSize: '0.875rem' }}
                  onClick={() => handleSaveEdit(todo.id)}
                >
                  保存
                </button>
                <button
                  type="button"
                  className="todo-delete"
                  onClick={handleCancelEdit}
                >
                  キャンセル
                </button>
              </div>
            ) : (
              <>
                <span
                  className="todo-text"
                  onDoubleClick={() => handleStartEdit(todo)}
                  style={{ cursor: 'pointer' }}
                  title="ダブルクリックして編集"
                >
                  {todo.text}
                </span>
                <div style={{ display: 'flex', gap: '4px' }}>
                  <button
                    type="button"
                    className="todo-delete"
                    style={{ color: '#3b82f6' }}
                    onClick={() => handleStartEdit(todo)}
                  >
                    編集
                  </button>
                  <button
                    type="button"
                    className="todo-delete"
                    onClick={() => handleDeleteTodo(todo.id)}
                  >
                    削除
                  </button>
                </div>
              </>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}
